namespace BWVR.Editor {
public static class ToolDeliveryChecks {
 static readonly BindingFlags F=BindingFlags.Instance|BindingFlags.NonPublic;
 static void Check(bool ok,string why){if(!ok)throw new Exception(why);}
 public static void VerifyModel(){var tools=new ToolTechnologyState();var stock=new ResourceState{wood=8,resin=4};Check(tools.Valid()&&tools.delivery==null,"Historical technology invented delivery");Check(JsonUtility.FromJson<ToolTechnologyState>(JsonUtility.ToJson(tools)).Valid(),"Empty optional delivery invalidated technology save");for(int i=0;i<3;i++)tools.Practice(0,1);Check(tools.OfferDelivery(stock,0,2,VillageTool.BoundAxe,0,Vector3.zero)&&stock.wood==8&&stock.resin==4&&!tools.learners[2].axeOwned,"Offer spent stock/granted equipment");Check(!tools.ReceiveDelivery(stock,ToolDeliverySource.None)&&!tools.learners[2].axeKnown,"Unattributed handoff taught design");stock.resin=0;Check(!tools.ReceiveDelivery(stock,ToolDeliverySource.Creature)&&!tools.learners[2].axeKnown,"Unfunded delivery taught design");stock.resin=4;Check(tools.ReceiveDelivery(stock,ToolDeliverySource.Creature)&&stock.wood==6&&stock.resin==2&&tools.learners[2].axeOwned&&tools.learners[2].sawAxe&&tools.delivery.source==ToolDeliverySource.Creature&&!tools.ReceiveDelivery(stock,ToolDeliverySource.Player)&&tools.Valid(),"Paid equipped handoff/attribution failed");Check(JsonUtility.FromJson<ToolTechnologyState>(JsonUtility.ToJson(tools)).Valid(),"Delivery save rejected");tools.delivery.recipient=999;Check(!tools.Valid(),"Invalid recipient accepted");Debug.Log("BWVR_TOOL_DELIVERY_MODEL_PASS: known design, no early grants, finite exact costs, actual recipient knowledge/equipment, once-only source and save validation");}
 public static void VerifyRuntime(Action<VillageResources> capture=null){
  Check(Application.isPlaying,"Enter Play mode");var slice=UnityEngine.Object.FindAnyObjectByType<QuestSlice>();var god=slice.GetComponentInChildren<CreatureHybrid>();var world=slice.GetComponentInChildren<VillageResources>();var nav=god.GetComponent<IslandNavigator>().world;Check(!nav.TreeNavigationPending,"Wait for navigation");var mind=god.GetComponent<CreatureCuriosity>();var field=typeof(QuestSlice).GetField("state",F);var original=(SliceState)field.GetValue(slice);var people=slice.GetComponentsInChildren<VillagerSocial>();var positions=people.Select(p=>p.transform.position).ToArray();var rotations=people.Select(p=>p.transform.rotation).ToArray();var gp=god.transform.position;var gr=god.transform.rotation;var handItems=(CarryItem[])typeof(QuestSlice).GetField("held",F).GetValue(slice);Check(handItems.All(i=>i==null),"Release held objects");var ideas=slice.GetComponentsInChildren<ConstructionInspiration>();var active=ideas.Select(i=>i.gameObject.activeSelf).ToArray();var cooldowns=god.Targets.Where(t=>t.affordance!=null).ToDictionary(t=>t.affordance,t=>t.affordance.cooldown);SliceState test=null;var receiver=world.Gatherers[2].GetComponent<VillagerSocial>();
  void Stage(VillageTool offered=VillageTool.BoundAxe){int recipient=offered==VillageTool.BoundAxe?2:1;receiver=world.Gatherers[recipient].GetComponent<VillagerSocial>();god.Interrupt("Tool delivery QA");foreach(var p in people){p.GetComponent<VillagerResourceGathering>().Cancel();p.GetComponent<VillagerExploration>().ResetTask();p.GetComponent<VillagerBlockPlay>().ResetTask();p.ResetTask();slice.GetComponentInChildren<VillageFamilies>()?.Release(p.GetComponent<VillagerRoutine>());slice.GetComponentInChildren<VillageCathedral>()?.Cancel(p.GetComponent<VillagerRoutine>());p.GetComponent<CarryItem>().held=false;}
   test=new SliceState{developmentFocus=true,observeWithoutFoodWork=true,water=100,crops=100,hunger=.05f};test.resources=JsonUtility.FromJson<ResourceState>(JsonUtility.ToJson(world.State));test.Resources.wood=8;test.Resources.resin=4;for(int i=0;i<3;i++)test.Tools.Practice(0,offered==VillageTool.BoundAxe?1:2);field.SetValue(slice,test);god.NewSeason();world.ResetWorld();slice.SetSanctuaryOpen(false);foreach(var p in people){p.Memory.lastFrightAt=-100;p.Memory.injury=0;p.Memory.trust=.6f;p.transform.position=world.StoreApproach+Vector3.up*nav.Scale*600;}foreach(var idea in ideas)idea.gameObject.SetActive(false);foreach(var a in cooldowns.Keys)a.cooldown=100000;
   bool placed=false;for(int i=0;i<24&&!placed;i++){var wanted=world.StoreApproach+Quaternion.Euler(0,i*15,0)*Vector3.forward*nav.Scale*22;if(receiver.GetComponent<IslandNavigator>().CanPlace(wanted,out var at)&&nav.Sample(at,nav.creature,3,out _)){receiver.transform.position=at;receiver.GetComponent<IslandNavigator>().ResetRoute();placed=true;}}Check(placed,"No receiver stage");world.Advance(.05f,false);Check(world.Delivery?.Active==true&&world.Delivery.recipient==recipient&&world.Delivery.tool==offered,"No useful forester tool offered");bool visible=false;for(int i=0;i<24&&!visible;i++){var wanted=world.DeliveryItem.transform.position+Quaternion.Euler(0,i*15,0)*Vector3.forward*nav.Scale*18;if(!nav.Sample(wanted,nav.creature,4,out var at))continue;god.transform.position=nav.ProjectFoot(at,nav.creature);god.transform.LookAt(new Vector3(world.DeliveryItem.transform.position.x,god.transform.position.y,world.DeliveryItem.transform.position.z));god.GetComponent<IslandNavigator>().ResetRoute();Physics.SyncTransforms();visible=world.CanOfferDelivery;}Check(visible,"No witnessed reachable workshop tool");
  }
  void Tick(float dt,bool ai=true){if(ai)god.Tick(dt);else test.Hybrid.time+=dt;world.Advance(dt,test.paused);}
  void PlayerDrop(){var tool=world.DeliveryItem;Check((bool)typeof(QuestSlice).GetMethod("TryGrab",F).Invoke(slice,new object[]{1,tool}),"Native player tool pickup failed");typeof(QuestSlice).GetMethod("Release",F).Invoke(slice,new object[]{1,new Ray(receiver.transform.position+Vector3.up*nav.Scale*30,Vector3.down)});}
  try{
   Stage();Check(world.FreeWood==6&&world.FreeResin==2&&!world.Gatherers[2].TryMakeTool(VillageTool.BoundAxe),"Materials double-reserved / recipient self-crafted");Check(god.Guide(GuidanceIntent.Help,world.DeliveryItem.GetComponent<HybridTarget>()),"Contextual delivery help rejected");for(int i=0;i<1500&&mind.Holding!=world.DeliveryItem;i++)Tick(.05f);Check(mind.Current==CreatureCuriosity.Phase.ToolDelivery&&mind.Holding==world.DeliveryItem&&world.DeliveryClaimed&&!test.Tools.learners[2].axeOwned&&test.Resources.wood==8,"Native selected tool pickup failed / early equipment award");capture?.Invoke(world);var recipientAt=receiver.transform.position;bool movedReceiver=false;for(int k=0;k<16&&!movedReceiver;k++){var wanted=recipientAt+Quaternion.Euler(0,k*22.5f,0)*Vector3.forward*nav.Scale*10;if(receiver.GetComponent<IslandNavigator>().CanPlace(wanted,out var at)&&god.CanReach(at)){receiver.transform.position=at;receiver.GetComponent<IslandNavigator>().ResetRoute();movedReceiver=world.TryToolDestination(out _);}}Check(movedReceiver,"No moving-recipient stage");Physics.SyncTransforms();test.paused=true;string paused=JsonUtility.ToJson(test);god.Tick(5);world.Advance(5,true);Check(paused==JsonUtility.ToJson(test),"Paused delivery advanced");test.paused=false;
   test.Hybrid.time+=20;world.Advance(.01f,false);typeof(QuestSlice).GetMethod("Save",F).Invoke(slice,null);typeof(QuestSlice).GetMethod("Load",F).Invoke(slice,null);test=(SliceState)field.GetValue(slice);god.NewSeason();foreach(var a in cooldowns.Keys)a.cooldown=100000;world.DeliveryItem.GetComponent<CreatureAffordance>().cooldown=0;world.Advance(.01f,false);Check(world.CanOfferDelivery,"Resume fixture cannot offer: feasible="+world.DeliveryFeasible+" visible="+god.CanSeeCue(world.DeliveryItem.GetComponent<HybridTarget>(),false,true)+" available="+world.DeliveryItem.GetComponent<CreatureAffordance>().Available+" time="+test.Hybrid.time);Check(test.Valid()&&world.Delivery.Active&&!world.DeliveryClaimed&&!world.DeliveryItem.held&&!test.Tools.learners[2].axeOwned&&test.Resources.wood==8,"Native pending resume kept ownership/paid early");
   for(int i=0;i<2400&&world.Delivery.Active;i++)Tick(.05f);Check(world.Delivery.status==ToolDeliveryStatus.Delivered&&world.Delivery.source==ToolDeliverySource.Creature&&test.Tools.learners[2].axeOwned&&test.Tools.learners[2].sawAxe&&test.Resources.wood==6&&test.Resources.resin==2&&!world.DeliveryClaimed&&!world.DeliveryItem.held&&!world.DeliveryItem.gameObject.activeSelf,"Native carry/follow/place/equip failed: "+world.Delivery.status+" phase="+mind.Current+" time="+test.Hybrid.time+" opened="+world.Delivery.openedAt+" explanation="+god.Explanation+" history="+string.Join("; ",god.Journal.Capture().Reverse().Take(6).Select(e=>e.kind+":"+e.reason)));Check(test.Hybrid.receipt.eligible&&test.Hybrid.receipt.action==CreatureAction.RespondToGuidance&&test.Hybrid.receipt.situation==CreatureSituation.HelpRequested&&!test.Hybrid.receipt.fetched,"Tool handoff learned as toy fetch");float trust=receiver.Memory.trust;Check(god.Feedback(true)&&!god.Feedback(true)&&!world.ConfirmToolDelivery(ToolDeliverySource.Creature)&&receiver.Memory.trust==trust&&test.Resources.wood==6,"Duplicate teaching / handoff charge");Check(JsonUtility.FromJson<SliceState>(JsonUtility.ToJson(test)).Valid(),"Delivered equipment save invalid");
   Stage();float playerTrust=receiver.Memory.trust;PlayerDrop();Check(world.Delivery.status==ToolDeliveryStatus.Delivered&&world.Delivery.source==ToolDeliverySource.Player&&test.Tools.learners[2].axeOwned&&test.Resources.wood==6&&receiver.Memory.trust==playerTrust&&!test.Hybrid.receipt.eligible,"Native player gift misattributed / not equipped");
   Stage();test.paused=true;PlayerDrop();Check(world.Delivery.Active&&world.Delivery.playerArrivalPending&&!test.Tools.learners[2].axeOwned,"Paused placement committed equipment");test.paused=false;Tick(.05f,false);Check(world.Delivery.source==ToolDeliverySource.Player&&test.Tools.learners[2].axeOwned,"Paused player arrival lost attribution");
   Stage();Check(god.Guide(GuidanceIntent.Help,world.DeliveryItem.GetComponent<HybridTarget>()),"Interrupted help request rejected");for(int i=0;i<1500&&mind.Holding!=world.DeliveryItem;i++)Tick(.05f);Check(mind.Holding==world.DeliveryItem,"No interrupted delivery carry");god.Interrupt("Player lifted the creature");Check(!world.DeliveryClaimed&&!world.DeliveryItem.held&&test.Resources.wood==8&&!test.Tools.learners[2].axeOwned,"Interrupted carry kept lease / spent stock");
   Stage();Check((bool)typeof(QuestSlice).GetMethod("TryGrab",F).Invoke(slice,new object[]{1,world.DeliveryItem}),"Expiry player pickup unavailable");test.Hybrid.time=world.Delivery.expiresAt+1;world.Advance(.05f,false);Check(world.Delivery.status==ToolDeliveryStatus.Expired&&world.DeliveryItem.held&&world.DeliveryItem.gameObject.activeSelf&&world.DeliveryItem.GetComponentsInChildren<Renderer>().Length>0&&world.FreeWood==8&&!test.Tools.learners[2].axeOwned,"Held expiry hid tool / retained reservation / granted equipment");typeof(QuestSlice).GetMethod("Release",F).Invoke(slice,new object[]{1,new Ray(receiver.transform.position+Vector3.up*nav.Scale*30,Vector3.down)});
   Stage();test.Hybrid.time=13;world.Advance(.05f,false);Check(world.Delivery.status==ToolDeliveryStatus.Expired&&world.FreeWood==8&&world.FreeResin==4&&!world.DeliveryItem.gameObject.activeSelf&&test.Resources.wood==8&&!test.Tools.learners[2].axeOwned,"Unanswered request spent resources or starved self-crafting");
   Stage();Check(world.ClaimToolDelivery(),"Could not lease interrupt fixture");test.Resources.resin=0;Check(!world.ConfirmToolDelivery(ToolDeliverySource.Creature)&&!test.Tools.learners[2].axeKnown,"Material loss minted equipment/knowledge");world.ReleaseToolDelivery();world.Advance(.05f,false);Check(world.Delivery.status==ToolDeliveryStatus.Unavailable&&!world.DeliveryItem.gameObject.activeSelf,"Unavailable materials retained offer");
   Stage(VillageTool.CultivatingHoe);PlayerDrop();Check(world.Delivery.status==ToolDeliveryStatus.Delivered&&world.Delivery.source==ToolDeliverySource.Player&&test.Tools.learners[1].hoeOwned&&test.Tools.learners[1].sawHoe&&test.Resources.wood==6&&test.Resources.resin==3&&test.Valid(),"Hoe handoff / distinct material cost invalid");
   Debug.Log("BWVR_TOOL_DELIVERY_RUNTIME_PASS: actual useful offer/reservations, utility-selected pickup and carry/follow/place, pause, native pending Save/Load, exact paid equipment/knowledge, source-specific teaching, native player pickup/drop, paused attribution, expiry and stock-loss cleanup");
  }finally{god.Interrupt("Tool delivery QA finished");for(int i=0;i<2;i++){if(handItems[i]!=null){handItems[i].held=false;handItems[i].GetComponent<Collider>().enabled=true;handItems[i]=null;}}foreach(var p in people){p.GetComponent<CarryItem>().held=false;p.GetComponent<Collider>().enabled=true;}field.SetValue(slice,original);god.NewSeason();world.ResetWorld();world.Advance(.01f,false);foreach(var pair in cooldowns)pair.Key.cooldown=pair.Value;for(int i=0;i<ideas.Length;i++)ideas[i].gameObject.SetActive(active[i]);god.transform.SetPositionAndRotation(gp,gr);god.GetComponent<IslandNavigator>().ResetRoute();for(int i=0;i<people.Length;i++){people[i].transform.SetPositionAndRotation(positions[i],rotations[i]);people[i].GetComponent<IslandNavigator>().ResetRoute();}Physics.SyncTransforms();}
 }
